-- RPC used by the agent-sql edge function to execute arbitrary SQL with parameters.
-- Owned by postgres, SECURITY DEFINER, callable only by service_role.
-- The edge function authenticates with the project's SERVICE_ROLE_KEY,
-- so this RPC is unreachable from the anon/authenticated API surface.
--
-- Apply this either by:
--   (a) copying it into supabase/migrations/<timestamp>_agent_sql_rpc.sql and running `supabase db push`, or
--   (b) pasting it into the Supabase SQL editor once.

create or replace function public.agent_exec_sql(query text, params jsonb default '[]'::jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  result jsonb;
  param_array text[];
  i int;
  rc int;
begin
  if jsonb_typeof(params) <> 'array' then
    raise exception 'params must be a JSON array';
  end if;

  param_array := array[]::text[];
  for i in 0 .. jsonb_array_length(params) - 1 loop
    param_array := param_array || (params ->> i);
  end loop;

  begin
    -- Try as a row-returning statement.
    execute format(
      'select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from (%s) t',
      query
    )
    into result
    using variadic param_array;
    return result;
  exception when others then
    -- Fallback for INSERT/UPDATE/DELETE/DDL etc.
    execute query using variadic param_array;
    get diagnostics rc = row_count;
    return jsonb_build_object('rowCount', rc);
  end;
end;
$$;

revoke all on function public.agent_exec_sql(text, jsonb) from public;
revoke all on function public.agent_exec_sql(text, jsonb) from anon, authenticated;
grant execute on function public.agent_exec_sql(text, jsonb) to service_role;

comment on function public.agent_exec_sql(text, jsonb) is
  'Agent SQL proxy backend. Called only by the agent-sql edge function via service_role.';
